import java.util.*;
import java.util.stream.*;
class Main {
  public static void main(String[] args) {
    Map<Integer, Long> m = Stream.of("a", "bb", "cc", "d")
      .collect(Collectors.groupingBy(String::length, Collectors.counting()));
    System.out.println(m.get(1) + " " + m.get(2));
  }
}

