import java.util.List;
import java.util.stream.Collectors;
class Main {
  public static void main(String[] args) {
    List<Integer> xs = List.of(1, 2, 3);
    System.out.println(xs.stream().map(x -> x * 2).collect(Collectors.toList()));
  }
}

